    93	/// Normalize an owner type's source text to its bare index key:
    94	/// strip refs/pointers, smart-pointer wrappers are NOT peeled here (that is
    95	/// receiver peeling, `peel_type`), strip generic args, strip `dyn `/`impl `.
    96	pub fn owner_key(text: &str) -> String {
    97	    let t = text.trim();
    98	    let t = t.trim_start_matches("&mut ").trim_start_matches('&');
    99	    let t = t.trim_start_matches('*');
   100	    let t = t.trim_start_matches("dyn ").trim_start_matches("impl ");
   101	    let t = t.split('<').next().unwrap_or(t);
   102	    // C++ out-of-line `ns::Foo` declarator prefix -> last segment.
   103	    let t = t.rsplit("::").next().unwrap_or(t);
   104	    t.trim().to_string()
   105	}
   106	
   107	/// Interface lookup key (Go): strip `&`/`*` and a `pkg.` qualifier to the bare
   108	/// interface name. Returns `None` for a generic instantiation (`Foo[T]`), which
   109	/// is non-dispatchable (a recorded gap, never a key) — spec §6/§10.
   110	pub fn iface_key(text: &str) -> Option<String> {
   111	    let t = text
   112	        .trim()
   113	        .trim_start_matches('&')
   114	        .trim_start_matches('*')
   115	        .trim();
   116	    if t.contains('[') {
   117	        return None; // generic instantiation -> gap, not a key
   118	    }
   119	    let bare = t.rsplit('.').next().unwrap_or(t).trim();
   120	    if bare.is_empty() {
   121	        None
   122	    } else {
   123	        Some(bare.to_string())
   124	    }
   125	}
