   158	/// Filter interface-dispatch candidate ids by call arity, keeping each `id` iff
   159	/// `arity_admits` admits its recorded `MethodArity` (a missing entry → unknown →
   160	/// kept). Order-preserving; borrows the input slice.
   161	pub fn arity_filter<'a>(
   162	    impls: &'a [FunctionId],
   163	    arg_count: Option<usize>,
   164	    arg_spread: bool,
   165	    method_arity: &BTreeMap<FunctionId, MethodArity>,
   166	) -> Vec<&'a FunctionId> {
   167	    impls
   168	        .iter()
   169	        .filter(|id| arity_admits(arg_count, arg_spread, method_arity.get(id)))
   170	        .collect()
   171	}
