   173	/// Closed-list syntactic peel (spec section 2.3): refs/pointers and std wrappers,
   174	/// recursively; then generic args; then dyn/impl. NEVER Deref-semantic.
   175	pub fn peel_type(text: &str) -> String {
   176	    let mut t = text.trim();
   177	    loop {
   178	        let before = t;
   179	        t = t
   180	            .trim_start_matches("&mut ")
   181	            .trim_start_matches('&')
   182	            .trim_start_matches("*const ")
   183	            .trim_start_matches("*mut ")
   184	            .trim_start_matches('*')
   185	            .trim();
   186	        // Rust lifetime after a reference: `&'a Sender` / `&'a mut Sender`.
   187	        // Drop a leading `'lifetime` token (and an optional following `mut`).
   188	        if let Some(rest) = t.strip_prefix('\'') {
   189	            let rest = rest.trim_start_matches(|c: char| c.is_alphanumeric() || c == '_');
   190	            t = rest.trim().trim_start_matches("mut ").trim();
   191	        }
   192	        for w in ["Box", "Arc", "Rc", "Pin"] {
   193	            if let Some(inner) = t.strip_prefix(w) {
   194	                if let Some(inner) = inner.trim().strip_prefix('<') {
   195	                    if let Some(inner) = inner.strip_suffix('>') {
   196	                        t = inner.trim();
   197	                    }
   198	                }
   199	            }
   200	        }
   201	        if t == before {
   202	            break;
   203	        }
   204	    }
   205	    let t = t.trim_start_matches("dyn ").trim_start_matches("impl ");
   206	    t.split('<').next().unwrap_or(t).trim().to_string()
   207	}
