  1054	
  1055	        // calls: remove entries where the caller is in an excluded file.
  1056	        self.calls
  1057	            .retain(|caller, _| !exclude.contains(&caller.file));
  1058	
  1059	        // callers: remove CallSite entries where the caller is in an excluded file.
  1060	        for sites in self.callers.values_mut() {
  1061	            sites.retain(|s| !exclude.contains(&s.caller.file));
  1062	        }
  1063	        self.callers.retain(|_, v| !v.is_empty());
  1064	
